h1, h2, h3 { margin: 0 0 var(--s2); line-height: 1.2; }
h1 { font-size: 20px; letter-spacing: 0.02em; }
h2 { font-size: 12px; text-transform: uppercase; letter-spacing: 0.14em; color: var(--muted); }

/* ---------- masthead ---------- */

.masthead {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--s4);
  flex-wrap: wrap;
  padding-bottom: var(--s4);
  margin-bottom: var(--s5);
  border-bottom: 1px solid var(--line);
}

.masthead h1 span { color: var(--magenta); }

.masthead p {
  margin: 0;
  color: var(--muted);
  font-size: 13px;
}

/* ---------- two-column shell ---------- */

.controls {
  display: grid;
  grid-template-columns: minmax(280px, 360px) 1fr;
  gap: var(--s5);
  align-items: start;
}

.preview {
  display: flex;
  flex-direction: column;
  gap: var(--s4);
  min-width: 0;
}

@media (max-width: 900px) {
  .controls { grid-template-columns: 1fr; }
}

/* ---------- drop zone ---------- */

.dropzone {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: var(--s2);
  min-height: 148px;
  padding: var(--s5);
  text-align: center;
  color: var(--muted);
  background: var(--panel);
  border: 2px dashed var(--line);
  border-radius: var(--radius);
  cursor: pointer;
  transition: border-color 140ms ease, background 140ms ease, color 140ms ease;
}

.dropzone:hover,
.dropzone:focus-visible {
  border-color: var(--cyan);
  color: var(--text);
  outline: none;
}

.dropzone.is-dragover {
  border-color: var(--magenta);
  background: var(--panel-2);
  color: var(--text);
  box-shadow: 0 0 0 4px rgba(255, 61, 139, 0.14) inset;
}

.dropzone strong { color: var(--text); font-weight: 600; }
.dropzone small { font-size: 12px; }

/* ---------- film strip thumbnails ---------- */

.captions {
  display: flex;
  gap: var(--s2);
  overflow-x: auto;
  padding: var(--s2) 0 var(--s3);
  list-style: none;
  margin: 0;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  scrollbar-color: var(--line) transparent;
}

.captions li,
.captions .thumb {
  flex: 0 0 auto;
  width: 96px;
  height: 60px;
  border-radius: 4px;
  overflow: hidden;
  background: var(--panel-2);
  border: 1px solid var(--line);
  position: relative;
  cursor: pointer;
  transition: border-color 140ms ease, transform 140ms ease;
}

.captions img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.captions li:hover,
.captions .thumb:hover { border-color: var(--cyan); }

.captions .thumb.is-active {
  border-color: var(--magenta);
  transform: translateY(-2px);
}

.captions .thumb.is-active::after {
  content: "";
  position: absolute;
  inset: 0;
  box-shadow: 0 0 0 2px var(--magenta) inset;
  pointer-events: none;
}

/* ---------- segmented template buttons ---------- */

.templates {
  display: flex;
  gap: var(--s1);
  padding: var(--s1);
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  margin-bottom: var(--s4);
}

.templates button {
  flex: 1 1 auto;
  appearance: none;
  padding: var(--s2) var(--s3);
  font: inherit;
  font-size: 13px;
  color: var(--muted);
  background: transparent;
  border: 0;
  border-radius: 6px;
  cursor: pointer;
  transition: color 140ms ease, background 140ms ease;
}

.templates button:hover { color: var(--text); background: var(--panel-2); }

.templates button.is-active,
.templates button[aria-pressed="true"] {
  color: #0b0b0d;
  background: var(--cyan);
  font-weight: 600;
}

/* ---------- palettes ---------- */

.palettes {
  display: flex;
  flex-wrap: wrap;
  gap: var(--s2);
  margin-bottom: var(--s4);
}

.palettes button {
  width: 32px;
  height: 32px;
  padding: 0;
  border-radius: 50%;
  border: 2px solid var(--line);
  background: var(--panel-2);
  cursor: pointer;
  transition: border-color 140ms ease, transform 140ms ease;
}

.palettes button:hover { transform: scale(1.08); border-color: var(--text); }

.palettes button.is-active { border-color: var(--magenta); }

/* ---------- canvas frame ---------- */

canvas,
.canvas-frame {
  display: block;
  width: 100%;
  height: auto;
  border-radius: var(--radius);
  border: 1px solid var(--line);
  background: var(--panel);
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.45);
}

/* ---------- export ---------- */

.export {
  appearance: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--s2);
  width: 100%;
  padding: var(--s3) var(--s5);
  font: inherit;
  font-size: 15px;
  font-weight: 700;
  letter-spacing: 0.03em;
  color: #0b0b0d;
  background: linear-gradient(90deg, var(--magenta), var(--cyan));
  border: 0;
  border-radius: var(--radius);
  cursor: pointer;
  transition: filter 140ms ease, transform 140ms ease;
}

.export:hover { filter: brightness(1.12); }
.export:active { transform: translateY(1px); }

.export:disabled {
  cursor: not-allowed;
  filter: grayscale(0.6) brightness(0.7);
}

/* ---------- status ---------- */

.status {
  min-height: 20px;
  margin-top: var(--s3);
  font-size: 13px;
  color: var(--muted);
}

.status.is-error { color: var(--magenta); }
.status.is-ok { color: var(--cyan); }

/* ---------- misc ---------- */

button:focus-visible,
.dropzone:focus-visible {
  outline: 2px solid var(--cyan);
  outline-offset: 2px;
}

@media (max-width: 900px) {
  body { padding: var(--s4); }
  .masthead { margin-bottom: var(--s4); }
}
